sys_script_fix.script:
(function() {
    var updateSetId = '5c14a4d993f84310d4ce32ddfaba109a'; // Ciclo Demo Data
    var appScopeId = '0e145ac993f00310d4ce32ddfaba10be'; // Ciclo Application ID
    var tables = ['x_431220_ciclo_iniciativa', 'x_431220_ciclo_choice'];

    // 1. Force the session to the Ciclo Application Scope
    gs.setCurrentApplicationId(appScopeId);

    // 2. Force the session to the specific Update Set
    var gus = new GlideUpdateSet();
    if (!gus.set(updateSetId)) {
        gs.print('ERROR: Could not set Update Set. Verify the Sys ID.');
        return;
    }

    gs.print('>>> Recording into Scope: ' + appScopeId);
    gs.print('>>> Recording into Update Set: ' + updateSetId);

    // 3. Use GlideUpdateManager2 (compatible with Zurich/Australia releases)
    var manager = new GlideUpdateManager2();
    var totalAdded = 0;

    for (var i = 0; i < tables.length; i++) {
        var tableName = tables[i];
        var gr = new GlideRecord(tableName);
        gr.query();

        gs.print('>>> Processing ' + tableName + ': ' + gr.getRowCount() + ' records');

        while (gr.next()) {
            // This captures the record as an XML entry in the correctly set scope
            manager.saveRecord(gr);
            totalAdded++;
        }
    }

    gs.print('>>> FINISHED. Total XML entries added to Ciclo scope: ' + totalAdded);
})();
